/*
  PingGraph — STEP 1 : SENDER  (Waveshare ESP32-S3-ETH)
  Sends a dummy probe_t over ESP-NOW once a second: climbing seq + realistic
  fake ping data, so we prove the link + feed the graph later (steps 2-3 add
  real Ethernet/ICMP).

  Libraries: NONE to install — all ESP32 core:
    WiFi.h, esp_now.h, esp_wifi.h, and neopixelWrite() for the onboard WS2812.

  Compiler board: "ESP32S3 Dev Module"
    -> set "USB CDC On Boot: Enabled" or the Serial Monitor stays silent on USB-C.
*/

#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>

#define RGB_PIN 21            // Waveshare ESP32-S3-ETH onboard WS2812
#define ESPNOW_CHANNEL 1      // MUST match the receiver

// >>> paste the CYD's STA MAC here (it shows on the CYD screen + serial at boot).
// Leave as broadcast to just get it working first.
uint8_t PEER_MAC[6] = { 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF };

typedef struct __attribute__((packed)) {
  uint32_t seq;        // climbs every probe -> receiver detects lost packets
  uint16_t rtt_ms;     // round-trip ms (ignore when status != 0)
  uint8_t  status;     // 0=OK, 1=ping timeout/loss, 2=no IP / link down
} probe_t;

probe_t  pkt;
uint32_t seq = 0;
int      rttWalk = 20;        // fake ping random-walk state

// ESP-NOW send result -> LED. The callback's first arg changed in core 4.0.0.
#if ESP_ARDUINO_VERSION >= ESP_ARDUINO_VERSION_VAL(4,0,0)
void onDataSent(const wifi_tx_info_t *info, esp_now_send_status_t status) {
#else
void onDataSent(const uint8_t *mac, esp_now_send_status_t status) {
#endif
  if (status == ESP_NOW_SEND_SUCCESS) neopixelWrite(RGB_PIN, 0, 40, 0);  // green
  else                                neopixelWrite(RGB_PIN, 40, 0, 0);  // red
}

void setup() {
  Serial.begin(115200);
  delay(300);
  randomSeed(micros());
  neopixelWrite(RGB_PIN, 40, 40, 40);     // white = booting

  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  esp_wifi_set_channel(ESPNOW_CHANNEL, WIFI_SECOND_CHAN_NONE);
  Serial.print("Sender MAC: "); Serial.println(WiFi.macAddress());

  if (esp_now_init() != ESP_OK) { neopixelWrite(RGB_PIN,40,0,0); Serial.println("init fail"); return; }
  esp_now_register_send_cb(onDataSent);

  esp_now_peer_info_t peer = {};
  memcpy(peer.peer_addr, PEER_MAC, 6);
  peer.channel = ESPNOW_CHANNEL;
  peer.encrypt = false;
  if (esp_now_add_peer(&peer) != ESP_OK) { neopixelWrite(RGB_PIN,40,0,0); Serial.println("peer fail"); return; }
  Serial.println("Sender ready");
}

void loop() {
  rttWalk += random(-3, 4);
  if (rttWalk < 5)  rttWalk = 5;
  if (rttWalk > 60) rttWalk = 60;

  pkt.seq    = seq++;
  pkt.rtt_ms = rttWalk;
  pkt.status = 0;
  if (random(0, 15) == 0) pkt.rtt_ms = random(150, 400);  // occasional spike
  if (random(0, 25) == 0) pkt.status = 1;                 // occasional timeout

  esp_now_send(PEER_MAC, (uint8_t *)&pkt, sizeof(pkt));
  Serial.printf("sent seq=%lu rtt=%u status=%u\n",
                (unsigned long)pkt.seq, pkt.rtt_ms, pkt.status);
  delay(1000);
}
